"""
    Computes the size of output image after the convolution defined by the input arguments
    """
def conv_outsize(in_size: Any, kernel_size: Any, padding: Any, stride: Any) -> object {
    out_size = ((in_size - kernel_size) + (2 * padding)) // stride;
    out_size += 1;
    return out_size;
}

""" Turn a string into a positive integer. """
def string_to_int(string: Any, keyspace_chars: Any) -> object {
    output = 0;
    for char in string {
        output = (output * len(keyspace_chars)) + keyspace_chars.index(char);
    }
    return output;
}

