"""\
    Formats a dictionary into a string of key=value pairs.

    :param adict: dictionary to format
    :param sep: separator. Default ','
    :param sort_first: whether to sort the key-value pairs first before formatting
    :return: a string with the formatted dictionary

    """
def format_dictionary(adict: Any, sep: Any = ', ', sort_first: Any = True) -> object {
    preprocess = sorted if sort_first else lambda (x: Any) { x; };
    return sep.join('{}={}'.format(k, v) for (k, v) in preprocess(iter(adict.items())));
}

"""Sign function.

    :return -1 if x < 0, else return 1
    """
def sign(x: Any) -> object {
    if (x < 0) {
        return -1;
    } else {
        return 1;
    }
}

"""Introduced by Feng et al. 2008"""
def chaotic_inertia_weight(
    c1: Any, c2: Any, z: Any, max_iter: Any, current_iter: Any
) -> object {
    z = 4 * z * (1 - z);
    return (((c1 - c2) * ((max_iter - current_iter) / max_iter)) + (c2 * z));
}

